// 团队可见性通过同租户团队成员条件判断；平台凭据以 is_global=true 和租户共享投影追加返回。
func (q *Queries) ListTenantCredentials(ctx context.Context, arg ListTenantCredentialsParams) ([]ListTenantCredentialsRow, error) {
	rows, err := q.db.Query(ctx, listTenantCredentials,
		arg.TenantID,
		arg.UserID,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTenantCredentialsRow{}
	for rows.Next() {
		var i ListTenantCredentialsRow
		if err := rows.Scan(
			&i.TenantID,
			&i.ID,
			&i.IsGlobal,
			&i.Name,
			&i.Kind,
			&i.Ciphertext,
			&i.Nonce,
			&i.KeyVersion,
			&i.Fingerprint,
			&i.SharedScope,
			&i.CreatedBy,
			&i.LastUsedAt,
			&i.Revision,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TeamIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

